//! Reuse the production BlockPlacer and IsSelfBed trees, including inactive modes.
use super::*;
use crate::{bed_defender_runtime::BedDefenderRuntime,liquid_filler_runtime::LiquidFillerRuntime};
#[derive(Clone,Debug,PartialEq)]pub enum BedDefenderSetting{Value(String,Value),SelfBed(BedPlatesSetting),Place(LiquidFillerSetting)}
impl BedDefenderSetting{
    pub fn apply(self,r:&mut BedDefenderRuntime,blocks:&[String])->Result<(),ConfigError>{match self{
        Self::SelfBed(v)=>v.apply(&mut r.self_bed,blocks).map_err(|mut e|{e.path=e.path.replace("BedPlates.IgnoreSelfBed","BedDefender.SelfBed");e}),
        Self::Place(v)=>{let mut proxy=LiquidFillerRuntime{settings:Default::default(),placer:std::mem::take(&mut r.placer)};let result=v.apply(&mut proxy,blocks);r.placer=proxy.placer;result.map_err(|mut e|{e.path=e.path.replace("LiquidFiller.Placer","BedDefender.Place");e})},
        Self::Value(p,v)=>{let path=format!("BedDefender.{p}");match p.as_str(){"MaxLayers"=>r.settings.max_layers=parse_int(&v,&path)?,"AllowChests"=>r.settings.allow_chests=parse_bool(&v,&path)?,"RequiresSneak"=>r.settings.requires_sneak=parse_bool(&v,&path)?,_=>return Err(ConfigError::new(&path,"unknown BedDefender setting"))}Ok(())}
    }}
}
fn remap(v:&mut Value,old:&str,new:&str){match v{Value::Object(o)=>{if let Some(Value::String(k))=o.get_mut("key"){*k=k.replace(old,new);}for v in o.values_mut(){remap(v,old,new);}},Value::Array(a)=>for v in a{remap(v,old,new);},_=>{}}}
fn take(tree:&mut Value,name:&str)->Result<Value,ConfigError>{tree["value"].as_array_mut().and_then(|a|a.iter_mut().find(|v|v["name"]==name)).map(Value::take).ok_or_else(||ConfigError::new("BedDefender","shared configuration tree changed"))}
pub fn serialize_bed_defender(r:&BedDefenderRuntime,c:&CommonSettings,f:JsonFormat,d:&dyn Fn(&str)->String)->Result<Value,ConfigError>{
    let t=Tree{format:f,describe:d};let mut values=t.common(ModuleKind::BedDefender,c);let key=|p:&str|format!("liquidbounce.module.bedDefender.{p}");
    values.push(t.ranged("MaxLayers","INT",json!(r.settings.max_layers),json!({"from":1,"to":5}),"",&key("maxLayers")));
    values.push(t.leaf("AllowChests","BOOLEAN",json!(r.settings.allow_chests),&key("allowChests"),None));
    let describe=|k:&str|d(&k.replace("liquidbounce.module.bedPlates.ignoreSelfBed","liquidbounce.module.bedDefender.selfBed"));let mut tree=serialize_bed_plates(&r.self_bed.settings,c,f,&describe)?;let mut self_bed=take(&mut tree,"IgnoreSelfBed")?;self_bed["name"]=json!("SelfBed");remap(&mut self_bed,"liquidbounce.module.bedPlates.ignoreSelfBed","liquidbounce.module.bedDefender.selfBed");values.push(self_bed);
    let proxy=LiquidFillerRuntime{settings:Default::default(),placer:r.placer.clone()};let describe=|k:&str|d(&k.replace("liquidbounce.module.liquidFiller.placer","liquidbounce.module.bedDefender.place"));let mut tree=serialize_liquid_filler(&proxy,c,f,&describe)?;let mut place=take(&mut tree,"Placer")?;place["name"]=json!("Place");remap(&mut place,"liquidbounce.module.liquidFiller.placer","liquidbounce.module.bedDefender.place");values.push(place);
    values.push(t.leaf("RequiresSneak","BOOLEAN",json!(r.settings.requires_sneak),&key("requiresSneak"),None));Ok(t.group("BedDefender","TOGGLEABLE",values))
}
pub(super) fn parse_bed_defender(p:&mut SettingsPatch,root:&Nodes<'_>){
    for name in["MaxLayers","AllowChests","RequiresSneak"]{if let Some(v)=root.get(name){match value_of(v,&format!("BedDefender.{name}")){Ok(v)=>{let change=BedDefenderSetting::Value(name.into(),v.clone());match change.clone().apply(&mut BedDefenderRuntime::default(),&[]){Ok(())=>p.changes.push(SettingChange::BedDefender(change)),Err(e)=>p.issues.push(e)}},Err(e)=>p.issues.push(e)}}}
    if let Some(v)=root.get("SelfBed"){let mut v=(*v).clone();v["name"]=json!("IgnoreSelfBed");let proxy=json!({"name":"BedPlates","value":[v]});let root=nodes(&proxy,"BedPlates","BedPlates").unwrap();let mut patch=SettingsPatch{module:ModuleKind::BedPlates,changes:vec![],issues:vec![]};bed_plates::parse_bed_plates(&mut patch,&root);for c in patch.changes{if let SettingChange::BedPlates(v)=c{p.changes.push(SettingChange::BedDefender(BedDefenderSetting::SelfBed(v)));}}p.issues.extend(patch.issues.into_iter().map(|mut e|{e.path=e.path.replace("BedPlates.IgnoreSelfBed","BedDefender.SelfBed");e}));}
    if let Some(v)=root.get("Place"){let mut v=(*v).clone();v["name"]=json!("Placer");let proxy=json!({"name":"LiquidFiller","value":[v]});let root=nodes(&proxy,"LiquidFiller","LiquidFiller").unwrap();let mut patch=SettingsPatch{module:ModuleKind::LiquidFiller,changes:vec![],issues:vec![]};liquid_filler::parse_liquid_filler(&mut patch,&root);for c in patch.changes{if let SettingChange::LiquidFiller(v)=c{p.changes.push(SettingChange::BedDefender(BedDefenderSetting::Place(v)));}}p.issues.extend(patch.issues.into_iter().map(|mut e|{e.path=e.path.replace("LiquidFiller.Placer","BedDefender.Place");e}));}
}
#[cfg(test)]mod tests{
    use super::*;use liquidbounce_behaviors::bed_plates::{SelfMode,Slot};use std::collections::BTreeSet;
    #[test]fn bed_defender_config_inactive_selfbed_and_placer_roundtrip(){
        let mut source=BedDefenderRuntime::default();source.settings.max_layers=5;source.settings.allow_chests=true;source.settings.requires_sneak=true;source.self_bed.set_mode(SelfMode::Manual);source.self_bed.settings.loose=true;source.self_bed.settings.slots=BTreeSet::from([Slot::Head,Slot::Feet]);source.self_bed.settings.bed_distance=47.;source.self_bed.settings.track="key.keyboard.b".into();source.self_bed.settings.untrack="key.keyboard.n".into();source.placer.settings.rotation_mode="None".into();source.placer.settings.normal_post_move=true;source.placer.settings.placements=4;source.placer.crystals.none_instant=true;source.placer.crystals.normal_instant=true;source.placer.target_render.enabled=true;source.placer.placed_render.out_time=600;
        let common=CommonSettings{enabled:true,hidden:false,key_bind:Value::Null};for format in[JsonFormat::File,JsonFormat::Interop]{let encoded=serialize_bed_defender(&source,&common,format,&str::to_owned).unwrap();let root=nodes(&encoded,"BedDefender","BedDefender").unwrap();let mut patch=SettingsPatch{module:ModuleKind::BedDefender,changes:vec![],issues:vec![]};parse_bed_defender(&mut patch,&root);assert!(patch.issues.is_empty(),"{:?}",patch.issues);let mut result=BedDefenderRuntime::default();for c in patch.changes{if let SettingChange::BedDefender(v)=c{v.apply(&mut result,&[]).unwrap();}}assert_eq!(result.settings,source.settings);assert_eq!(result.self_bed.settings,source.self_bed.settings);assert_eq!(result.placer.settings,source.placer.settings);assert_eq!(result.placer.crystals,source.placer.crystals);assert_eq!(result.placer.rotations,source.placer.rotations);assert_eq!(result.placer.crystal_rotations,source.placer.crystal_rotations);assert_eq!(result.placer.target_render,source.placer.target_render);assert_eq!(result.placer.placed_render,source.placer.placed_render);}
    }
    #[test]fn bed_defender_mode_switch_resets_manual_and_bad_leaf_preserves_placer(){let mut r=BedDefenderRuntime::default();r.self_bed.set_mode(SelfMode::Manual);r.self_bed.manual=[3;3];BedDefenderSetting::SelfBed(BedPlatesSetting("IgnoreSelfBed".into(),json!("Color"))).apply(&mut r,&[]).unwrap();assert_eq!(r.self_bed.manual,[0;3]);let before=r.placer.settings.clone();assert!(BedDefenderSetting::Place(LiquidFillerSetting::Value("Placer.Cooldown".into(),json!({"from":8,"to":2}))).apply(&mut r,&[]).is_err());assert_eq!(r.placer.settings,before);}
}
